begin;

-- ODEIR public terms page only. Tenant workspaces and operational records are not touched.
do $$
declare
  v_site_id uuid;
  v_page_id uuid;
  v_document_id uuid;
  v_version integer;
  v_document jsonb;
begin
  select id into v_site_id
  from website.sites
  where site_key='marktone-main'
  limit 1;

  if v_site_id is null then
    raise exception 'odeir_platform_site_not_found';
  end if;

  v_document := private_app.website_builder_validate_document($terms${"schemaVersion":1,"settings":{"contentWidth":"wide","background":"#ffffff","customCss":""},"blocks":[{"id":"odeir-terms-hero","type":"hero","props":{"anchor":"top","eyebrow":"شروط الاستخدام والاشتراك","title":"قواعد واضحة للتشغيل… وحدود واضحة للمسؤولية.","body":"تنظم هذه الشروط استخدام موقع ومنصة أودير، والخطة المجانية والمدفوعة، وتغييرات الأسعار والحدود، والإلغاء والإيقاف، ومسؤولية مدير المنشأة، وخروج البيانات. تاريخ آخر تحديث والنفاذ: 28 أغسطس 2026.","imageUrl":"","imageAlt":"شروط استخدام واشتراك أودير","primaryLabel":"سياسة الخصوصية","primaryHref":"/p/privacy-policy","secondaryLabel":"حقوق البيانات","secondaryHref":"/p/data-rights"},"style":{"variant":"dark","align":"right","paddingY":96,"maxWidth":"wide","cssClass":"odeir-terms-hero"},"responsive":{}},{"id":"odeir-terms-toc","type":"toc","props":{"anchor":"contents","title":"في هذه الصفحة","items":[{"title":"نطاق العلاقة","href":"#contract"},{"title":"حدود الخطة المجانية","href":"#free-plan"},{"title":"الأسعار والتجديد","href":"#pricing"},{"title":"التعليق والإنهاء","href":"#suspension"},{"title":"خروج البيانات","href":"#data-exit"},{"title":"مسؤولية المنشأة","href":"#responsibility"},{"title":"حدود مسؤولية أودير","href":"#liability"},{"title":"الاستخدام المقبول","href":"#acceptable-use"}]},"style":{"variant":"light","align":"right","paddingY":22,"maxWidth":"wide","cssClass":"odeir-legal-toc"},"responsive":{}},{"id":"odeir-terms-summary","type":"stats","props":{"anchor":"summary","eyebrow":"في دقيقة واحدة","title":"أهم ما يجب أن تعرفه","body":"هذه النقاط ملخص مساعد، والنص الكامل في الأقسام التالية هو المرجع.","columns":4,"items":[{"value":"مرنة","title":"الخطة المجانية ليست ثابتة للأبد","description":"يجوز تعديل مكوناتها وحدودها أو استبدالها أو إيقافها وفق هذه الشروط."},{"value":"مسؤول","title":"مدير المنشأة يدير الاستخدام","description":"وهو مسؤول عن المستخدمين والبيانات والخدمات والقرارات الصادرة من مساحته."},{"value":"في أي وقت","title":"يمكن للعميل الإلغاء","description":"مع مراعاة المستحقات ومدة الاشتراك وشروط التجديد."},{"value":"تصدير أو حذف","title":"خروج منظم للبيانات","description":"وفق الخيار المتاح والمحدد عند الإنهاء وبعد التحقق من الصلاحية."}]},"style":{"variant":"light","align":"center","paddingY":76,"maxWidth":"wide","cssClass":"odeir-terms-summary"},"responsive":{}},{"id":"odeir-terms-contract","type":"cards","props":{"anchor":"contract","eyebrow":"نطاق الاتفاق","title":"ما الذي يحكم العلاقة؟","body":"باستخدام الخدمة أو إنشاء الحساب أو قبول عرض أو طلب، تقر بأنك مخول عن المنشأة وتوافق على الوثائق المطبقة.","columns":3,"items":[{"title":"هذه الشروط","description":"تحكم الاستخدام العام والحسابات والخطط والسلوك المقبول والتعليق والإنهاء وحدود المسؤولية."},{"title":"عرض السعر أو اتفاقية الطلب","description":"يحدد الخطة والمدة والسعر والخصائص ومستوى الخدمة والشروط الخاصة، وتكون له الأولوية عند التعارض الصريح."},{"title":"السياسات المرتبطة","description":"تشمل سياسة الخصوصية وأمن المعلومات وملفات الارتباط وحقوق البيانات، وتعد جزءًا مكملًا بحسب موضوعها."},{"title":"أهلية ممثل المنشأة","description":"يجب أن يكون المستخدم مخولًا قانونيًا، وأن يقدم بيانات صحيحة ومحدثة ويحافظ على وسائل الدخول."},{"title":"حساب المنشأة","description":"الحساب مخصص للمنشأة المسجلة ولا يجوز بيعه أو تأجيره أو نقله أو فتحه لجهة أخرى دون موافقة مكتوبة."},{"title":"اللغة والنسخة المعتمدة","description":"تكون النسخة العربية هي المرجع عند اختلاف الترجمة، ويظهر تاريخ آخر تحديث في كل سياسة."}]},"style":{"variant":"light","align":"right","paddingY":84,"maxWidth":"wide","cssClass":"odeir-policy-data"},"responsive":{}},{"id":"odeir-terms-free","type":"cards","props":{"anchor":"free-plan","eyebrow":"الخطة المجانية","title":"مجانية البداية لا تعني ثبات الحدود أو بقاء كل الخصائص بلا مقابل","body":"الخطة المجانية وسيلة لبدء التشغيل، وتخضع للحدود والسياسات المنشورة وقت الاستخدام.","columns":3,"items":[{"title":"عدد المستخدمين والأدوار","description":"يجوز تحديد أو تعديل عدد المستخدمين النشطين، المقاعد، الفروع، الأدوار الإدارية أو الحسابات الفرعية."},{"title":"المساحة والملفات","description":"يجوز تحديد أو تعديل سعة التخزين، أحجام الملفات، المرفقات، النسخ، مدة الاحتفاظ أو عدد المستندات."},{"title":"السجلات والعمليات","description":"يجوز وضع حدود للعملاء والمتدربين والفرص والمهام والفواتير والبرامج والعمليات الشهرية أو الإجمالية."},{"title":"الأتمتة والتكاملات","description":"يجوز تحديد عدد عمليات الأتمتة والرسائل والمزامنات وواجهات الربط، أو جعل بعضها ضمن خطة أو إضافة مدفوعة."},{"title":"التقارير والدعم","description":"يجوز تحديد عمق السجل التاريخي، التصدير، التقارير المتقدمة، أولوية الدعم، وساعات أو قنوات المساندة."},{"title":"تعديل أو استبدال الخطة","description":"يجوز لأودير تعديل الخطة المجانية أو إعادة تسميتها أو استبدالها أو وقفها، ولا ينشأ عن استخدامها حق دائم في حدود أو خصائص سابقة."}]},"style":{"variant":"light","align":"right","paddingY":88,"maxWidth":"wide","cssClass":"odeir-terms-free"},"responsive":{}},{"id":"odeir-terms-notice","type":"alert","props":{"anchor":"changes","icon":"!","eyebrow":"كيف نطبق التغييرات؟","title":"إشعار معقول عند التغيير الجوهري — وفوري عند الخطر","body":"عندما يؤثر تعديل جوهري في خطة نشطة، نسعى لإبلاغ مدير المنشأة عبر البريد أو داخل الحساب قبل سريانه بمدة معقولة كلما كان ذلك ممكنًا. يجوز التطبيق الفوري عند وجود متطلب نظامي، خطر أمني، إساءة استخدام، حماية عاجلة للخدمة أو ظرف تقني لا يحتمل التأخير. ويُعد استمرار الاستخدام بعد تاريخ السريان قبولًا بالتغيير بالقدر الذي يسمح به النظام، مع بقاء خيار الإلغاء وخروج البيانات وفق هذه الشروط.","tone":"warning"},"style":{"variant":"light","align":"right","paddingY":58,"maxWidth":"reading","cssClass":"odeir-terms-notice"},"responsive":{}},{"id":"odeir-terms-pricing","type":"cards","props":{"anchor":"pricing","eyebrow":"الأسعار والخطط المدفوعة","title":"السعر يتغير للمستقبل، لا بأثر رجعي على مدة مدفوعة","body":"ما لم تنص اتفاقية الطلب على غير ذلك، تطبق القواعد التالية.","columns":3,"items":[{"title":"تغيير الأسعار","description":"يجوز تعديل أسعار التجديد أو الإضافات أو حدود الخطط للمستقبل، مع إشعار مناسب قبل دورة التجديد أو تاريخ السريان."},{"title":"رفض السعر الجديد","description":"إذا لم تقبل المنشأة السعر أو الخطة الجديدة، يمكنها إلغاء التجديد قبل سريانه واختيار تصدير البيانات أو حذفها وفق مسار الإنهاء."},{"title":"الضرائب ورسوم الأطراف","description":"الأسعار قد لا تشمل الضرائب أو رسوم بوابات الدفع أو الاتصالات أو مزودي التكامل، وتتحملها المنشأة ما لم يذكر خلاف ذلك."},{"title":"الفوترة والاستحقاق","description":"تستحق الرسوم وفق الطلب أو الفاتورة. قد تتوقف الخصائص المدفوعة أو الحساب عند التأخر بعد الإشعارات وفترة المعالجة المطبقة."},{"title":"الاسترداد","description":"لا تُرد الرسوم المدفوعة عن مدة بدأت إلا إذا أوجب النظام أو نص اتفاق مكتوب أو أوقفت أودير خدمة مدفوعة دون مخالفة من العميل ولم توفر بديلًا مكافئًا."},{"title":"الخدمات الاختيارية","description":"الإضافات والاستشارات والتنفيذ والتكاملات وخدمات الأطراف الثالثة قد يكون لها أسعار وشروط ونطاقات مستقلة."}]},"style":{"variant":"light","align":"right","paddingY":84,"maxWidth":"wide","cssClass":"odeir-terms-pricing"},"responsive":{}},{"id":"odeir-terms-lifecycle","type":"timeline","props":{"anchor":"suspension","eyebrow":"التعليق والإنهاء","title":"متى يجوز إيقاف الخدمة؟ وماذا يحدث بعدها؟","body":"نوازن بين استمرارية التشغيل وحماية المنصة وبقية العملاء والالتزام النظامي.","items":[{"value":"01","title":"تنبيه ومعالجة","description":"عند مخالفة قابلة للعلاج أو تأخر مالي، قد نرسل إشعارًا ونمنح مهلة مناسبة لمعالجة السبب بحسب الخطة والاتفاق."},{"value":"02","title":"تعليق محدود","description":"يجوز تقييد وظيفة أو مستخدم أو تكامل بدل إيقاف الحساب كاملًا متى كان ذلك كافيًا لحماية الخدمة."},{"value":"03","title":"تعليق فوري","description":"يجوز الإيقاف الفوري عند اختراق أو خطر أمني، نشاط غير مشروع، محاولة تجاوز الصلاحيات، إساءة جسيمة، طلب ملزم من جهة مختصة أو خطر على الآخرين."},{"value":"04","title":"إنهاء من أودير","description":"يجوز لأودير إنهاء خطة أو خدمة لأسباب تجارية أو تقنية أو نظامية مع إشعار معقول متى أمكن، أو فورًا عند سبب جوهري لا يمكن علاجه."},{"value":"05","title":"إنهاء من المنشأة","description":"يجوز للمنشأة إلغاء الخدمة في أي وقت؛ ويوقف الإلغاء التجديد المستقبلي، مع بقاء الرسوم والمستحقات السابقة والمدة المدفوعة وفق الاتفاق."},{"value":"06","title":"خروج البيانات والإغلاق","description":"بعد الإنهاء تختار المنشأة، ضمن المهلة والقنوات المحددة، تصديرًا آمنًا للبيانات أو حذفها نهائيًا، ثم يغلق الوصول وتنتهي إمكانية الاسترداد بعد اكتمال المسار."}]},"style":{"variant":"dark","align":"right","paddingY":90,"maxWidth":"reading","cssClass":"odeir-terms-lifecycle"},"responsive":{}},{"id":"odeir-terms-exit","type":"cards","props":{"anchor":"data-exit","eyebrow":"الإلغاء وخروج البيانات","title":"لا نحبس بيانات المنشأة داخل المنصة","body":"تخضع التفاصيل الفنية ونوع الملفات لما تدعمه الخطة والوحدات المفعلة وقت الطلب.","columns":3,"items":[{"title":"إلغاء في أي وقت","description":"يستطيع مدير المنشأة المخول طلب الإلغاء عبر القناة المعتمدة. وقد نطلب تحققًا إضافيًا لحماية الحساب ومنع الحذف الاحتيالي."},{"title":"تسليم آمن","description":"يمكن طلب نسخة منظمة من البيانات المتاحة للتصدير، عبر وسيلة أو رابط آمن، مع مراعاة حقوق الآخرين والأسرار والقيود النظامية."},{"title":"حذف نهائي","description":"يمكن طلب حذف بيانات المساحة بدل التصدير. بعد بدء الحذف واكتمال المهلة الفنية قد يتعذر استرجاع البيانات."},{"title":"مهلة الانتقال","description":"تحدد أودير مهلة معقولة في إشعار الإنهاء أو اتفاقية الطلب لإتمام التصدير. وقد تقصر أو تنعدم عند خطر أمني أو أمر ملزم."},{"title":"الاحتفاظ الإلزامي","description":"يجوز الاحتفاظ ببيانات محدودة محجوبة عن الاستخدام العادي عندما يوجب النظام أو يلزم لإثبات الحقوق أو مكافحة الاحتيال."},{"title":"النسخ الاحتياطية","description":"تخرج النسخ الاحتياطية من دورة الاستخدام العادي وتُحذف وفق جدولها الفني، ولا تستخدم لغرض جديد أثناء فترة الإطفاء."}]},"style":{"variant":"paper","align":"right","paddingY":86,"maxWidth":"wide","cssClass":"odeir-terms-exit"},"responsive":{}},{"id":"odeir-terms-responsibility","type":"cards","props":{"anchor":"responsibility","eyebrow":"مسؤولية المنشأة ومديرها","title":"أودير توفر الأداة… والمنشأة مسؤولة عن طريقة استخدامها","body":"مدير المنشأة هو صاحب القرار في الحساب، ويضمن التزام مستخدميه بهذه الشروط.","columns":3,"items":[{"title":"مشروعية البيانات","description":"الحصول على الأساس النظامي والإشعارات والموافقات اللازمة لجمع بيانات العملاء والمتدربين والموظفين وإدخالها أو ربطها بالمنصة."},{"title":"المستخدمون والصلاحيات","description":"دعوة الأشخاص المناسبين، منح أقل صلاحية لازمة، إلغاء وصول المغادرين، حماية الأجهزة وبيانات الدخول، ومراجعة الأنشطة."},{"title":"صحة المدخلات","description":"التحقق من دقة البيانات والأسعار والجداول والحضور والفواتير والقوالب والرسائل قبل الاعتماد أو الإرسال."},{"title":"الخدمات المقدمة","description":"تتحمل المنشأة ومديرها كامل المسؤولية عن الدورات والخدمات والعروض والالتزامات والشهادات والمحتوى والتواصل المقدم لعملائها أو متدربيها."},{"title":"الأتمتة والقرارات","description":"مراجعة قواعد التوزيع والرسائل والأتمتة والتقارير والاقتراحات وعدم الاعتماد عليها وحدها في قرار قانوني أو مالي أو مهني أو عالي الأثر."},{"title":"الاستخدام المستقبلي","description":"أي ميزة أو تكامل أو استخدام تنشئه المنشأة حاليًا أو مستقبلًا، بما في ذلك استخدام غير مقصود أو خارج الغرض المعلن، يقع على مسؤوليتها ما لم يكن ناتجًا مباشرة عن إخلال من أودير."}]},"style":{"variant":"light","align":"right","paddingY":88,"maxWidth":"wide","cssClass":"odeir-terms-responsibility"},"responsive":{}},{"id":"odeir-terms-liability","type":"cards","props":{"anchor":"liability","eyebrow":"حدود مسؤولية أودير","title":"حدود عادلة بقدر ما يسمح به النظام","body":"لا تهدف هذه البنود إلى استبعاد مسؤولية لا يجوز نظامًا استبعادها، بل إلى توزيع المخاطر بحسب من يسيطر على القرار والاستخدام.","columns":3,"items":[{"title":"ليست طرفًا في خدمة المنشأة","description":"أودير ليست مقدم الدورة أو الاستشارة أو البيع ولا طرفًا في علاقة المنشأة بعملائها أو متدربيها أو موظفيها، ما لم ينص عقد مستقل على ذلك."},{"title":"الخدمة «كما هي ومتاحة»","description":"نسعى للاستمرارية والأمان، لكن لا نضمن خلو الخدمة من كل خطأ أو توقف، ولا تكون مستويات التوفر أو الاستجابة ملزمة إلا إذا وردت في اتفاقية خدمة."},{"title":"استخدامات المنشأة","description":"لا تتحمل أودير نتائج المحتوى أو الرسائل أو الأسعار أو القرارات أو الأتمتة أو الاستخدام الحالي أو المتوقع مستقبلًا الذي تنشئه المنشأة أو مستخدموها."},{"title":"البيانات والتكاملات","description":"لا نتحمل أخطاء المدخلات أو حذف المنشأة أو مشاركة بيانات الدخول أو تعطل مزود خارجي أو تغيير واجهته أو سياسته خارج سيطرتنا المعقولة."},{"title":"الأضرار غير المباشرة","description":"بالقدر المسموح نظامًا، لا تشمل المسؤولية الأرباح الفائتة أو السمعة أو الفرص أو الخسائر غير المباشرة أو التبعية أو العقابية."},{"title":"الحد الأقصى والاستثناءات","description":"ما لم ينص اتفاق مكتوب على غير ذلك، لا تتجاوز المسؤولية المباشرة مجموع الرسوم المدفوعة لأودير عن الخدمة المتأثرة خلال الاثني عشر شهرًا السابقة، دون مساس بالغش أو الخطأ الجسيم أو الحقوق التي لا يجوز استبعادها."}]},"style":{"variant":"light","align":"right","paddingY":88,"maxWidth":"wide","cssClass":"odeir-terms-liability"},"responsive":{}},{"id":"odeir-terms-use","type":"faq","props":{"anchor":"acceptable-use","eyebrow":"الاستخدام المقبول","title":"ممنوعات تحمي حسابك وبقية العملاء","body":"قد تؤدي المخالفة إلى التقييد أو التعليق أو الإنهاء والإبلاغ للجهة المختصة عند اللزوم.","items":[{"title":"هل يجوز تجاوز الصلاحيات أو اختبار الحماية؟","description":"لا. يُمنع الوصول غير المصرح أو المسح والفحص والهندسة العكسية وتعطيل الخدمة أو التحايل على الحدود إلا بتصريح مكتوب ونطاق اختبار محدد."},{"title":"هل يجوز استخدام المنصة للرسائل الجماعية؟","description":"فقط مع أساس نظامي وموافقات وقنوات تسمح بذلك. يحظر الإزعاج والاحتيال وانتحال الهوية والمحتوى المضلل أو غير المشروع."},{"title":"هل يجوز رفع كلمات مرور أو مفاتيح سرية في الحقول العامة؟","description":"لا. يجب استخدام مسارات التكامل الآمنة وعدم إدخال أسرار أو بيانات شديدة الحساسية في حقول أو ملاحظات غير مخصصة لها."},{"title":"هل يجوز بيع الحساب أو مشاركته مع منشأة أخرى؟","description":"لا، إلا بموافقة أودير وترتيب تعاقدي يضمن عزل البيانات والصلاحيات. لكل منشأة مساحتها وسياقها المستقل."},{"title":"هل يمكن الاعتماد على تقرير أو اقتراح آلي دون مراجعة؟","description":"لا في القرارات القانونية أو المالية أو المهنية أو عالية الأثر. يجب أن يراجع شخص مخول المخرجات وسياقها ودقة البيانات."},{"title":"من يملك المحتوى والبيانات؟","description":"تحتفظ المنشأة بحقوقها في بياناتها ومحتواها، وتمنح أودير ترخيصًا محدودًا بالقدر اللازم لتشغيل الخدمة. وتبقى المنصة وبرمجياتها وتصميمها وموادها ملكًا لأصحابها."}]},"style":{"variant":"light","align":"right","paddingY":82,"maxWidth":"reading","cssClass":"odeir-terms-use"},"responsive":{}},{"id":"odeir-terms-law","type":"linkBlock","props":{"anchor":"law","icon":"§","eyebrow":"القانون والتواصل","title":"النظام المطبق وحل النزاع","body":"تخضع العلاقة للأنظمة المعمول بها في المملكة العربية السعودية بالقدر المنطبق، وللجهة والاختصاص المحددين في اتفاقية الطلب أو العقد. قبل التقاضي، يسعى الطرفان بحسن نية إلى معالجة النزاع عبر القنوات الرسمية. إذا تعذر الحل، تختص المحاكم أو جهة الفصل المختصة وفق الاتفاق والنظام. لا تمنع هذه الشروط أي حق أو حماية لا يجوز التنازل عنها نظامًا.","linkLabel":"راجع سياسة الخصوصية","href":"/p/privacy-policy"},"style":{"variant":"light","align":"right","paddingY":58,"maxWidth":"reading","cssClass":"odeir-terms-law"},"responsive":{}},{"id":"odeir-terms-cta","type":"cta","props":{"anchor":"contact","eyebrow":"قبل التعاقد أو الإلغاء","title":"ثبّت أي استثناء أو التزام خاص كتابةً.","body":"الوعود أو الحدود أو مستويات الخدمة الخاصة لا تكون ملزمة إلا إذا ظهرت في عرض السعر أو اتفاقية الطلب أو تأكيد رسمي من أودير. للاستفسارات الرسمية: hello@marktone.sa.","buttonLabel":"العودة إلى أودير","buttonHref":"/"},"style":{"variant":"brand","align":"right","paddingY":72,"maxWidth":"wide","cssClass":"odeir-terms-cta"},"responsive":{}}]}$terms$::jsonb);

  update website.pages
  set title='شروط الاستخدام والاشتراك',
      menu_label='شروط الاستخدام',
      excerpt='الشروط المنظمة للخطط والأسعار والتعليق والإلغاء وخروج البيانات ومسؤولية المنشأة.',
      body='',
      content=v_document,
      template_key='builder',
      seo_title='شروط الاستخدام والاشتراك | أودير',
      seo_description='شروط استخدام أودير والخطة المجانية والمدفوعة وتعديل الحدود والأسعار والإلغاء والإيقاف وخروج البيانات وحدود المسؤولية.',
      status='published',
      visibility='public',
      page_kind='legal',
      canonical_url='/p/terms-of-use',
      robots='index,follow',
      published_at=coalesce(published_at,now()),
      updated_at=now()
  where site_id=v_site_id and slug='terms-of-use' and status<>'archived'
  returning id into v_page_id;

  if v_page_id is null then
    raise exception 'odeir_terms_page_not_found';
  end if;

  insert into website.content_documents(
    site_id,entity_type,entity_id,schema_version,draft_document,published_document,
    draft_updated_at,published_at
  ) values(
    v_site_id,'page',v_page_id,1,v_document,v_document,now(),now()
  )
  on conflict(site_id,entity_type,entity_id) do update set
    schema_version=1,
    draft_document=excluded.draft_document,
    published_document=excluded.published_document,
    draft_updated_at=now(),
    published_at=now(),
    updated_at=now()
  returning id into v_document_id;

  select coalesce(max(version_number),0)+1 into v_version
  from website.content_document_versions
  where content_document_id=v_document_id;

  insert into website.content_document_versions(
    content_document_id,version_number,version_kind,document,note
  ) values(
    v_document_id,v_version,'published',v_document,
    'تحديث شروط الخطط والأسعار والإلغاء وخروج البيانات وحدود المسؤولية'
  );
end
